            font-size: 4rem;
            margin-bottom: 1rem;
            text-transform: uppercase;
            letter-spacing: 3px;
            text-shadow: 3px 3px 6px rgba(0,0,0,0.7);
        }

        .hero-content p {
            font-size: 1.3rem;
            margin-bottom: 2rem;
            color: #cccccc;
        }

        .cta-button {
            display: inline-block;
            padding: 15px 40px;
            background: var(--primary-color);
            color: var(--text-light);
            text-decoration: none;
            border-radius: 5px;
            font-weight: bold;
            text-transform: uppercase;
            transition: all 0.3s;
            box-shadow: 0 4px 15px rgba(222, 155, 53, 0.3);
        }

        .cta-button:hover {
            background: var(--accent-color);
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(255, 107, 53, 0.4);
        }

        /* Features Section */
        .features {
            padding: 4rem 2rem;
            max-width: 1200px;
            margin: 0 auto;
        }

        .section-title {
            text-align: center;
            font-size: 2.5rem;
            margin-bottom: 3rem;
            color: var(--primary-color);
            text-transform: uppercase;
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
        }

        .feature-card {
            background: var(--bg-light);
            padding: 2rem;
            border-radius: 10px;
            transition: transform 0.3s;
            border: 2px solid transparent;
        }

        .feature-card:hover {
            transform: translateY(-5px);
            border-color: var(--primary-color);
        }

        .feature-card h3 {
            color: var(--primary-color);
            margin-bottom: 1rem;
            font-size: 1.5rem;
        }

        .feature-card p {
            color: #cccccc;
            line-height: 1.8;
        }

        /* Weapons Section */
        .weapons {
            background: var(--bg-light);
            padding: 4rem 2rem;
        }

        .weapons-container {
            max-width: 1200px;
            margin: 0 auto;
        }

        .weapon-categories {
            display: flex;
            justify-content: center;
            gap: 1rem;
            margin-bottom: 2rem;
            flex-wrap: wrap;
        }

        .category-btn {
            padding: 10px 20px;
            background: var(--secondary-color);
            color: var(--text-light);
            border: none;
            border-radius: 5px;
            cursor: pointer;
            transition: all 0.3s;
            font-weight: bold;
        }

        .category-btn:hover,
        .category-btn.active {
            background: var(--primary-color);
        }

        .weapon-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 1.5rem;
        }

        .weapon-card {
            background: var(--bg-dark);
            padding: 1.5rem;
            border-radius: 8px;
            text-align: center;
            transition: all 0.3s;
        }

        .weapon-card:hover {
            transform: scale(1.05);
            box-shadow: 0 5px 15px rgba(222, 155, 53, 0.3);
        }

        .weapon-icon {
            font-size: 3rem;
            margin-bottom: 1rem;
        }

        .weapon-name {
            font-weight: bold;
            color: var(--primary-color);
            margin-bottom: 0.5rem;
        }

        .weapon-price {
            color: #4CAF50;
            font-size: 1.2rem;
        }

