            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 2rem;
            font-weight: bold;
        }

        .map-info {
            padding: 1.5rem;
        }

        .map-name {
            font-size: 1.3rem;
            color: var(--primary-color);
            margin-bottom: 0.5rem;
        }

        .map-mode {
            color: #888;
            font-size: 0.9rem;
        }

        /* News Section */
        .news {
            background: var(--bg-light);
            padding: 4rem 2rem;
        }

        .news-container {
            max-width: 1200px;
            margin: 0 auto;
        }

        .news-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
        }

        .news-card {
            background: var(--bg-dark);
            border-radius: 10px;
            padding: 1.5rem;
            transition: all 0.3s;
        }

        .news-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 5px 20px rgba(0,0,0,0.5);
        }

        .news-date {
            color: var(--primary-color);
            font-size: 0.9rem;
            margin-bottom: 0.5rem;
        }

        .news-title {
            font-size: 1.2rem;
            margin-bottom: 1rem;
            color: var(--text-light);
        }

        .news-excerpt {
            color: #aaa;
            line-height: 1.6;
        }

        .read-more {
            color: var(--primary-color);
            text-decoration: none;
            font-weight: bold;
            display: inline-block;
            margin-top: 1rem;
