            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 2rem;
            text-align: center;
        }

        .stat-box {
            background: rgba(255,255,255,0.05);
            padding: 2rem;
            border-radius: 10px;
            backdrop-filter: blur(10px);
        }

        .stat-number {
            font-size: 3rem;
            color: var(--primary-color);
            font-weight: bold;
        }

        .stat-label {
            color: #aaa;
            margin-top: 0.5rem;
            text-transform: uppercase;
            letter-spacing: 1px;
